12.4 3. 테스트 가능한 코드 작성 예시
테스트하기 좋은 함수는 하나의 명확한 작업만 수행해야 합니다.

# 데이터를 필터링하고 필요한 열만 선택하는 함수
wrangle_data &lt;- function(data) {
  res &lt;- data %&gt;%
    filter(SAFFL == "Y") %&gt;% 
    select(STUDYID, USUBJID, SEX, TRT01A, SAFFL)
  return(res)
}

# 빈도를 계산하는 함수
calculate_counts &lt;- function(data) {
  res &lt;- data %&gt;%
    group_by(TRT01A, SEX) %&gt;%
    count(name = "n")
  return(res)
}
